CREATE TABLE external_statements(integrator_id VARCHAR(64) NOT NULL,id UUID NOT NULL,provider VARCHAR(64) NOT NULL,statement_reference VARCHAR(128) NOT NULL,fingerprint CHAR(64) NOT NULL,source JSONB NOT NULL,snapshot JSONB NOT NULL,PRIMARY KEY(integrator_id,id),UNIQUE(integrator_id,provider,statement_reference));
CREATE TABLE statement_investigations(integrator_id VARCHAR(64) NOT NULL,id UUID NOT NULL,report_id UUID NOT NULL,actor_id VARCHAR(128) NOT NULL,reason_code VARCHAR(64) NOT NULL,fingerprint CHAR(64) NOT NULL,related_journal_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(integrator_id,id),FOREIGN KEY(integrator_id,report_id) REFERENCES external_statements(integrator_id,id));
CREATE FUNCTION reject_statement_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Statement evidence and investigations are immutable';END $$;
CREATE TRIGGER statement_guard BEFORE UPDATE OR DELETE ON external_statements FOR EACH ROW EXECUTE FUNCTION reject_statement_mutation();
CREATE TRIGGER investigation_guard BEFORE UPDATE OR DELETE ON statement_investigations FOR EACH ROW EXECUTE FUNCTION reject_statement_mutation();
